// Общие шаги для #550e01db (Billing → Payment method у тарифа, назначенного вручную).
// ПИШУТ данные на проде: только «בדיקה» (через targetRow из admin-plans), отмена — revokeIfAssigned в finally.
import { expect, Locator, Page } from '@playwright/test';
import { openPlansTab, targetRow, dialogFields, choosePlan, isoDate } from '../admin-plans/plans-helpers';

export const REASON = 'QA-autotest #550e01db';
export const UNTIL_DAYS = 30;
// Приложение перечитывает назначение раз в ≤60 с (на QA 18–21 с); запас до 90 с.
export const PROPAGATION_MS = 90_000;

export const TRIAL_TEXT = 'Add a card to keep your subscription active after the trial.';
export const grantedTextEn = (date: string) =>
  `Your plan is granted by Techory until ${date}, so no card is needed until then.`;
export const grantedTextHe = (date: string) =>
  `החבילה שלך הוקצתה על ידי Techory עד ${date}, ולכן אין צורך בכרטיס עד אז.`;

/** Дата так, как её показывает HE-интерфейс: «6 בנוב׳ 2026». */
export function heDate(offsetDays: number): string {
  const d = new Date();
  d.setDate(d.getDate() + offsetDays);
  return d.toLocaleDateString('he-IL', { day: 'numeric', month: 'short', year: 'numeric' });
}

export function addPaymentButton(page: Page): Locator {
  return page.getByRole('button', { name: 'Add Payment Method' })
    .or(page.getByRole('link', { name: 'Add Payment Method' }));
}

/** Admin: назначить «בדיקה» тариф (строка должна быть без назначения). */
export async function assignPlan(admin: Page, planName: string) {
  await openPlansTab(admin);
  const row = await targetRow(admin);
  await row.getByRole('button', { name: 'Assign plan', exact: true }).click();
  const f = dialogFields(admin);
  await expect(f.dialog).toBeVisible();
  await choosePlan(admin, f.plan, planName);
  await f.until.fill(isoDate(UNTIL_DAYS));
  await f.reason.fill(REASON);
  await f.save.click();
  await expect(f.dialog).toBeHidden();
  const after = await targetRow(admin);
  await expect(after.getByRole('button', { name: 'Change / extend', exact: true })).toBeVisible();
  await expect(after.getByRole('button', { name: 'Revoke', exact: true })).toBeVisible();
}

/** Admin: сменить назначенный тариф через «Change / extend». */
export async function changePlan(admin: Page, planName: string) {
  await openPlansTab(admin);
  const row = await targetRow(admin);
  await row.getByRole('button', { name: 'Change / extend', exact: true }).click();
  const f = dialogFields(admin);
  await expect(f.dialog).toBeVisible();
  await choosePlan(admin, f.plan, planName);
  await f.until.fill(isoDate(UNTIL_DAYS));
  await f.reason.fill(REASON);
  await f.save.click();
  await expect(f.dialog).toBeHidden();
  await expect(await targetRow(admin)).toContainText(planName);
}
